@font-face{font-family:Ravi;src:url("{{ Vite::asset('public/assets/fonts/ravi/Ravi-VF.woff2') }}") format("woff2");font-style:normal;font-weight:100 900;font-display:swap}
.landing-page{--ink:#172840;--muted:#546375;--blue:#205c9b;--line:#e4eaf0;--paper:#fff;--soft:#f6f9fc;direction:rtl;margin:0;background:var(--paper);color:var(--ink);font-family:Ravi,Tahoma,sans-serif;font-size:16px;line-height:1.8}
.landing-page *{box-sizing:border-box}.landing-page a{text-decoration:none}.landing-container{width:min(100% - 48px,1280px);margin-inline:auto}
.landing-header{position:relative;z-index:10;border-bottom:1px solid #eaf0f5;background:#fff}.landing-header-inner{height:84px;display:flex;align-items:center;justify-content:space-between;gap:32px}
.landing-brand{display:inline-flex;align-items:center;gap:11px;color:var(--ink);font-size:22px;font-weight:850;white-space:nowrap}.landing-brand-symbol{display:block;width:36px;height:36px;flex-shrink:0}.landing-brand-wordmark{display:block;width:auto;height:27px;max-width:74px;object-fit:contain}
.landing-nav{display:flex;align-items:center;gap:32px}.landing-nav a,.landing-login{color:#45566a;font-size:14px;font-weight:650;white-space:nowrap}.landing-auth-links{display:flex;align-items:center;gap:10px;flex-shrink:0}
.landing-auth-links .landing-login{min-height:42px;display:inline-flex;align-items:center;justify-content:center;border:1px solid #d5e1ec;border-radius:11px;background:#fff;padding:8px 16px;color:#173a60;font-size:13px;font-weight:800;box-shadow:0 2px 5px rgba(20,48,76,.04)}.landing-auth-links .landing-register{border-color:#0069ff;background:linear-gradient(135deg,#1479ff,#0057df);color:#fff}
.landing-hero{position:relative;isolation:isolate;overflow:hidden;background:linear-gradient(105deg,#f5f9fc 0%,#fff 54%,#f7fafd 100%)}.home-hero{min-height:590px;background:#f8fbff}.home-hero .landing-hero-art{position:absolute;inset:0;z-index:-2;opacity:1;background:#f8fbff url("{{ Vite::asset('resources/images/hero-concepts/voice-current-desktop.webp') }}") center/cover no-repeat;pointer-events:none;-webkit-mask-image:none;mask-image:none}
.home-hero-grid{position:relative;z-index:1;display:grid;grid-template-columns:minmax(0,1fr);align-content:center;gap:22px;min-height:590px;padding-block:52px 46px}.home-hero-message{width:60%;max-width:760px}
.home-hero-message h1{max-width:none;margin:13px 0 0;color:#001739;font-size:clamp(34px,3.2vw,46px);font-weight:850;letter-spacing:-.045em;line-height:1.38;white-space:nowrap}.home-hero-message h1 span{color:#0069ff}.home-hero-message>p:not(.landing-kicker){max-width:570px;margin:20px 0 0;color:#30465f;font-size:18px;line-height:2}
.landing-kicker{display:flex;align-items:center;gap:12px;color:var(--blue);font-size:13px;font-weight:800;letter-spacing:.01em}.home-hero-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:26px}.landing-button{display:inline-flex;align-items:center;justify-content:center;gap:22px;min-height:52px;padding:10px 23px;border-radius:10px;font-size:14px;font-weight:800}.home-hero-actions .landing-button{min-height:49px;padding:10px 20px;gap:12px}.landing-button-primary,.home-hero-actions .landing-button-primary{background:#0069ff;color:#fff}.landing-button-outline,.home-hero-actions .landing-button-outline{border:1px solid #b8cde0;background:rgba(255,255,255,.72);color:#153554}
.landing-hero-fade{position:absolute;inset:auto 0 0;height:200px;z-index:0;background:linear-gradient(transparent,#fff);pointer-events:none}.home-hero .landing-hero-fade{height:200px}
.home-section{padding:105px 0;scroll-margin-top:18px}.home-customers-section{background:#f6f9fc;border-block:1px solid #eaf0f5}.home-customers-inner{display:grid;grid-template-columns:minmax(250px,.85fr) minmax(0,1.5fr);align-items:center;gap:48px}.home-section-intro{max-width:790px}.home-customers-section .home-section-intro{max-width:440px}.home-section-intro h2{margin:11px 0 0;font-size:clamp(31px,3.2vw,45px);font-weight:850;line-height:1.46}.home-customers-section .home-section-intro h2{font-size:clamp(23px,2.2vw,29px);line-height:1.6}.home-customers-section .home-section-intro>p:last-child{margin:8px 0 0;color:var(--muted);font-size:13px;line-height:1.9}
.home-customer-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0;padding:0;border:0;list-style:none}.home-customer-list li{display:block;min-width:0;min-height:0;padding:0;border:0}.home-customer-link{position:relative;display:flex;min-height:148px;flex-direction:column;align-items:center;justify-content:center;gap:12px;border:1px solid #e3ebf3;border-radius:15px;background:#fff;padding:18px 14px 16px;color:var(--ink);text-align:center}.home-customer-logo{display:grid;width:100%;height:52px;place-items:center}.home-customer-logo img{display:block;width:auto;height:auto;max-width:145px;max-height:48px;object-fit:contain}
@media(max-width:900px){.landing-nav{gap:17px}.landing-nav a{font-size:12px}.landing-auth-links .landing-login{font-size:12px}.home-customers-inner{grid-template-columns:1fr;gap:20px}.home-customers-section .home-section-intro{max-width:620px}.home-hero-message{width:70%}}
@media(max-width:760px){.landing-container,.landing-header .landing-container,.home-hero>.landing-container,.home-section>.landing-container{width:min(100% - 36px,1280px)}.landing-header-inner{height:auto;min-height:70px;flex-wrap:wrap;gap:0 15px;padding-block:12px}.landing-brand{font-size:19px}.landing-nav{order:3;width:100%;overflow-x:auto;gap:22px;padding-top:10px;white-space:nowrap}.landing-nav a{font-size:13px}.landing-auth-links{gap:8px}.landing-auth-links .landing-login{margin-right:0;padding:5px 8px;font-size:11px}.home-hero{min-height:0;padding-bottom:0}.home-hero .landing-hero-art{height:100%;background-image:linear-gradient(180deg,rgba(250,252,255,.97) 0%,rgba(250,252,255,.9) 49%,rgba(250,252,255,.12) 80%),url("{{ Vite::asset('resources/images/hero-concepts/voice-current-mobile.webp') }}");background-position:center top,left bottom;background-size:100% 76%,auto 66%;background-repeat:no-repeat,no-repeat}.home-hero-grid{min-height:0;padding-block:62px 285px}.home-hero-message{width:100%;max-width:570px}.home-hero-message h1{font-size:clamp(18px,5vw,34px)}.home-hero-message>p:not(.landing-kicker){font-size:16px}.home-hero .landing-hero-fade{height:130px}.home-customers-section{padding:32px 0}.home-customers-inner{gap:17px}.home-customer-list{gap:8px}.home-customer-link{min-height:123px;gap:8px;padding:13px 7px}.home-customer-logo{height:43px}.home-customer-logo img{max-width:100%;max-height:39px}.home-section-intro h2{font-size:30px}}
@media(max-width:440px){.home-hero-grid{padding-block:50px 245px}.home-hero-actions{align-items:stretch;flex-direction:column;max-width:290px}.home-hero-actions .landing-button{justify-content:space-between}.home-customer-list{grid-template-columns:1fr}.home-customer-link{min-height:84px;flex-direction:row;justify-content:flex-start;padding:13px 15px;text-align:right}.home-customer-logo{width:86px;flex:none}}
